clc; clearvars;

addpath(genpath("proc_functions\"));

data_dir = "C:\Users\tely1\PhD\o3_processed_data"; %[control:filebrowser:7bbf]{"position":[12,50]}
ccny_data_dir = dir(fullfile(data_dir,"ccny/"));
glass_data_dir = dir(fullfile(data_dir,"glass/"));
tempo_data_dir = dir(fullfile(data_dir,"tempo/"));

date   = datetime(datetime("2024-10-31", "InputFormat", "uuuu-MM-dd"),'Format','uuuuMMdd'); %[control:datePicker:06fb]{"position":[19,70]}
lat             = 40.8216; %[control:editfield:31ee]{"position":[19,26]}
lon             = -73.9479; %[control:editfield:49e0]{"position":[19,27]}
max_distance_m  = 10000; %[control:editfield:70e1]{"position":[19,24]}
max_sza         = 70; %[control:editfield:2c26]{"position":[19,21]}
max_vza         = 70; %[control:editfield:31c1]{"position":[19,21]}
max_cld_frac    = 1; %[control:editfield:14da]{"position":[19,20]}

max_time_min    = 30; %[control:editfield:5daf]{"position":[19,21]}

colocate_params.lat = lat;
colocate_params.lon = lon;

colocate_params.max_distance_m = max_distance_m;
colocate_params.max_sza = max_sza;
colocate_params.max_vza = max_vza;
colocate_params.max_cld_frac = max_cld_frac;
%%
%[text] load ccny
idx = find(contains(string({ccny_data_dir.name}), string(date)));
ccny_data = load(fullfile(ccny_data_dir(idx).folder, ccny_data_dir(idx).name));
%%
%[text] load glass
idx = find(contains(string({glass_data_dir.name}), string(date)));
glass_data = read_glass(fullfile(glass_data_dir(idx).folder, glass_data_dir(idx).name));
%%
%[text] load tempo
idx = find(contains(string({tempo_data_dir.name}), string(date)));
tempo_files = fullfile(string({tempo_data_dir(idx).folder}), string({tempo_data_dir(idx).name}));

% TODO: cache the colocation data
tempo_data = tempo_o3_colocate(tempo_files,colocate_params);
%%
%[text] convert lidar profiles to DU

%%
%[text] find closest ccny and glass profiles to tempo
tempo_times = tempo_data.time;
ccny_times = ccny_data.times_avg';
glass_times = glass_data.time;

n_prof_tempo = length(tempo_times);
prof_id = 4; %[control:slider:768a]{"position":[11,12]}

O3_tempo = tempo_data.o3_prof(:,prof_id);
alt_tempo = tempo_data.alt(:,prof_id);
alt_bounds_tempo = tempo_data.alt_bounds(:,:,prof_id);

id_valid_ccny  = find(minutes(abs(tempo_times(prof_id) - ccny_times)) <= max_time_min);
id_valid_glass = find(minutes(abs(tempo_times(prof_id) - glass_times)) <= max_time_min);

[~,id_temp_ccny] = min(abs(tempo_times(prof_id) - ccny_times));
[~,id_temp_glass] = min(abs(tempo_times(prof_id) - glass_times));

id_ccny = id_valid_ccny(id_temp_ccny);
id_glass = id_valid_glass(id_temp_glass);
%%
NO3_ccny = ccny_data.N_o3_mg_merged(:,id_ccny);
alt_ccny = ccny_data.z_vec' .* 1e-3;

NO3_glass = glass_data.NO3(id_glass,:)';
NO3_glass(NO3_glass<0) = NaN;
alt_glass = glass_data.alt' .* 1e-3;

figure; %[output:4f04e4f6]
plot(NO3_ccny,alt_ccny,'DisplayName','ccny') %[output:4f04e4f6]
hold on %[output:4f04e4f6]
plot(NO3_glass,alt_glass,'DisplayName','glass') %[output:4f04e4f6]
hold off %[output:4f04e4f6]
xlabel("ozone number density (m^-3)") %[output:4f04e4f6]
ylabel("altitude (km)") %[output:4f04e4f6]
xlim([0 2e18]) %[output:4f04e4f6]
ylim([0 10]) %[output:4f04e4f6]
grid on  %[output:4f04e4f6]
legend %[output:4f04e4f6]
figure; %[output:610cd9df]
plot(O3_tempo,alt_tempo, '-o'); %[output:610cd9df]
xlabel("ozone (DU)") %[output:610cd9df]
ylabel("altitude (km)") %[output:610cd9df]
ylim([0 10]) %[output:610cd9df]
grid on %[output:610cd9df]

